using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Splines;using TutorialFramework;
[InitializeOnLoad]public static class BatchCollisionRuntime{
 const string P="BatchCollision.";static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static string Report="Temp/V12BatchNext/collision-runtime.txt";
 [Serializable]public class Job{public string nameA,nameB;public int slotA,slotB,slotC,slotD;}
 [Serializable]public class Jobs{public Job[] jobs;}
 [Serializable]public class Shape{public Vector3[] controls;public float radius;}
 [Serializable]public class Result{public int index;public string a,b;public Shape beforeA,beforeB,afterA,afterB;public float milliseconds;}
 static bool Running{get=>SessionState.GetBool(P+"run",false);set=>SessionState.SetBool(P+"run",value);}static int Stage{get=>SessionState.GetInt(P+"stage",0);set=>SessionState.SetInt(P+"stage",value);}static double Due{get=>SessionState.GetFloat(P+"due",0);set=>SessionState.SetFloat(P+"due",(float)value);}
 static Jobs jobs;static int index;static FreeLabWindController wind;
 static BatchCollisionRuntime(){EditorApplication.update+=Tick;}
 static Shape Read(FreeLabWire w){var c=w.GetComponentInChildren<SplineContainer>(true);var s=c.Spline;var controls=new List<Vector3>();for(int i=0;i<s.Count-1;i++){var a=s[i];var b=s[i+1];var p=c.transform.TransformPoint((Vector3)a.Position);var q=c.transform.TransformPoint((Vector3)b.Position);controls.AddRange(new[]{p,p+c.transform.TransformVector((Vector3)Unity.Mathematics.math.rotate(a.Rotation,a.TangentOut)),q+c.transform.TransformVector((Vector3)Unity.Mathematics.math.rotate(b.Rotation,b.TangentIn)),q});}return new Shape{controls=controls.ToArray(),radius=c.GetComponent<SplineExtrude>().Radius*Mathf.Abs(c.transform.lossyScale.x)};}
 static FreeLabWire Wire(FreeLabWireDefinition d){var w=d.wireParentTemplate.GetComponent<FreeLabWire>();return w?w:d.wireParentTemplate.AddComponent<FreeLabWire>();}
 static GameObject Plug(FreeLabEndpoint e,int i)=>wind.sockets.Single(s=>s.endpoint==e).plugs[i];
 static void Tick(){if(!Running&&File.Exists("Temp/batch-collision-runtime.flag")&&!EditorApplication.isPlayingOrWillChangePlaymode&&!EditorApplication.isCompiling&&!EditorApplication.isUpdating){File.Delete("Temp/batch-collision-runtime.flag");if(SceneManager.GetActiveScene().isDirty){File.WriteAllText(Report,"BLOCKED dirty scene");return;}Running=true;Stage=0;File.WriteAllText(Report,"");File.WriteAllText("Temp/V12BatchNext/collision-results.jsonl","");EditorSceneManager.OpenScene("Assets/_Project/Scenes/Main Menu.unity");Due=EditorApplication.timeSinceStartup+7;EditorApplication.EnterPlaymode();return;}
 if(!Running||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.timeSinceStartup<Due)return;
 try{if(Stage==4){if(EditorApplication.isPlayingOrWillChangePlaymode)return;EditorSceneManager.OpenScene("Assets/_Project/Scenes/PV Lab.unity");File.AppendAllText(Report,"FINISHED\n");Running=false;return;}var manager=InteractionManager.Instance;if(!manager){Due=EditorApplication.timeSinceStartup+1;return;}
 if(Stage==0){manager.currentMode=ExperimentMode.Guided;var launcher=Resources.FindObjectsOfTypeAll<MainMenuExperimentLauncher>().Single(l=>l.gameObject.scene==SceneManager.GetActiveScene()&&new SerializedObject(l).FindProperty("storyboardId").stringValue=="Speed Curve Characteristics");launcher.GetComponent<UnityEngine.UI.Button>().onClick.Invoke();Stage=1;Due=EditorApplication.timeSinceStartup+8;return;}
 if(Stage==1){manager.SetFree();Stage=2;Due=EditorApplication.timeSinceStartup+10;return;}
 if(Stage==2){wind=Resources.FindObjectsOfTypeAll<FreeLabWindController>().Single(w=>w.gameObject.scene==SceneManager.GetActiveScene());if(!wind.IsReady){Due=EditorApplication.timeSinceStartup+1;return;}var popup=wind.speedSlider.transform.parent.GetComponent<CanvasGroup>();var buttons=popup.transform.parent.GetComponentsInChildren<UnityEngine.UI.Button>(true);buttons.Single(b=>b.name=="Wind Speed Button").onClick.Invoke();buttons.Single(b=>b.name=="View Turbine").onClick.Invoke();jobs=JsonUtility.FromJson<Jobs>(File.ReadAllText("Temp/V12BatchNext/collision-jobs.json"));index=0;Stage=3;}
 if(Stage==3){var list=(IList<FreeLabWire>)typeof(FreeLabManager).GetProperty("connections",flags).GetValue(wind.lab);for(int n=0;n<2&&index<jobs.jobs.Length;n++,index++){var job=jobs.jobs[index];list.Clear();var a=wind.definitions.Single(d=>d.name==job.nameA);var b=wind.definitions.Single(d=>d.name==job.nameB);var wa=Wire(a);var wb=Wire(b);wa.Configure(wind.lab,a.endpointA,a.endpointB,Plug(a.endpointA,job.slotA),Plug(a.endpointB,job.slotB));wb.Configure(wind.lab,b.endpointA,b.endpointB,Plug(b.endpointA,job.slotC),Plug(b.endpointB,job.slotD));var result=new Result{index=index,a=job.nameA,b=job.nameB,beforeA=Read(wa),beforeB=Read(wb)};list.Add(wa);var watch=System.Diagnostics.Stopwatch.StartNew();wb.Configure(wind.lab,b.endpointA,b.endpointB,Plug(b.endpointA,job.slotC),Plug(b.endpointB,job.slotD));watch.Stop();result.milliseconds=(float)watch.Elapsed.TotalMilliseconds;result.afterA=Read(wa);result.afterB=Read(wb);File.AppendAllText("Temp/V12BatchNext/collision-results.jsonl",JsonUtility.ToJson(result)+"\n");list.Clear();}
 if(index==100)ScreenCapture.CaptureScreenshot("Temp/V12BatchNext/popup-final.png");if(index%50<2)File.AppendAllText(Report,index+" / "+jobs.jobs.Length+"\n");if(index==jobs.jobs.Length){Stage=4;EditorApplication.ExitPlaymode();Due=EditorApplication.timeSinceStartup+2;}}
 }catch(Exception e){File.AppendAllText(Report,"FAIL "+e+"\n");Stage=4;if(EditorApplication.isPlaying)EditorApplication.ExitPlaymode();else Running=false;}}
}
